import{_ as o,a0 as d,w as p,s as r,ao as a,I as e,x as t,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Linux 上使用 stat 命令查看文件狀態 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 stat 命令查看文件狀態 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 stat 命令查看文件狀態 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 stat 命令查看文件狀態 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210820 Check file status on Linux with the stat command","title":"在 Linux 上使用 stat 命令查看文件狀態","tag":"202109","desc":""},"relativePath":"202109/20210820 Check file status on Linux with the stat command.md","filePath":"[post].md"}'),u={name:"202109/20210820 Check file status on Linux with the stat command.md"};function f(m,s,x,c,k,g){const n=d("Link");return p(),r("div",null,[s[36]||(s[36]=a('<h1 id="在-linux-上使用-stat-命令查看文件狀態" tabindex="-1">在 Linux 上使用 stat 命令查看文件狀態 <a class="header-anchor" href="#在-linux-上使用-stat-命令查看文件狀態" aria-label="Permalink to “在 Linux 上使用 stat 命令查看文件狀態”">​</a></h1><blockquote><p>獲取到任何文件或文件系統的所有信息，僅需要一條 Linux 命令。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202109/10/072912ouo04jchatqazq53.jpg" alt=""></p><p>在 GNU <code>coreutils</code> 軟件包中包含 <code>stat</code> 命令，它提供了關於文件和文件系統包括文件大小、節點位置、訪問權限和 SELinux 上下文，以及創建和修改時間等各種元數據。通常情況下，你需要多個不同命令獲取的信息，而這一個命令就可以實現。</p><h3 id="在-linux-上安裝-stat-命令" tabindex="-1">在 Linux 上安裝 stat 命令 <a class="header-anchor" href="#在-linux-上安裝-stat-命令" aria-label="Permalink to “在 Linux 上安裝 stat 命令”">​</a></h3><p>在 Linux 系統中，可能已經預裝了 <code>stat</code> 命令，因為它屬於核心功能軟件包，通常默認包含在 Linux 發行版裏。</p><p>如果系統中沒有安裝 <code>stat</code> 命令，你可以使用包管理器安裝 <code>coreutils</code> 軟件包。</p>',7)),e("p",null,[s[1]||(s[1]=t("另外，你可以 ",-1)),l(n,{href:"https://www.gnu.org/software/coreutils/"},{default:i(()=>[...s[0]||(s[0]=[t("通過源碼編譯安裝 coreutils 包",-1)])]),_:1}),s[2]||(s[2]=t("。",-1))]),s[37]||(s[37]=a(`<h3 id="獲取文件狀態" tabindex="-1">獲取文件狀態 <a class="header-anchor" href="#獲取文件狀態" aria-label="Permalink to “獲取文件狀態”">​</a></h3><p>運行 <code>stat</code> 命令可以獲取指定文件或目錄易讀的狀態信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat planets.xml</span></span>
<span class="line"><span>  File: planets.xml</span></span>
<span class="line"><span>  Size: 325      Blocks: 8     IO Block: 4096   regular file</span></span>
<span class="line"><span>Device: fd03h/64771d    Inode: 140217      Links: 1</span></span>
<span class="line"><span>Access: (0664/-rw-rw-r--)  Uid: (1000/tux)   Gid: (100/users)</span></span>
<span class="line"><span>Context: unconfined_u:object_r:user_home_t:s0</span></span>
<span class="line"><span>Access: 2021-08-17 18:26:57.281330711 +1200</span></span>
<span class="line"><span>Modify: 2021-08-17 18:26:58.738332799 +1200</span></span>
<span class="line"><span>Change: 2021-08-17 18:26:58.738332799 +1200</span></span>
<span class="line"><span> Birth: 2021-08-17 18:26:57.281330711 +1200</span></span></code></pre></div><p>輸出的信息易懂，但是包含了很多的信息，這裏是 <code>stat</code> 所包含的項：</p><ul><li><code>File</code>：文件名</li><li><code>Size</code>：文件大小，以字節表示</li><li><code>Blocks</code>：在硬盤驅動器上為文件保留的數據塊的數量</li><li><code>IO Block</code>：文件系統塊大小</li><li><code>regular file</code>：文件類型（普通文件、目錄、文件系統）</li><li><code>Device</code>：文件所在的設備</li><li><code>Inode</code>：文件所在的 Inode 號</li><li><code>Links</code>：文件的鏈接數</li><li><code>Access</code>、<code>UID</code>、<code>GID</code>：文件權限、用户和組的所有者</li><li><code>Context</code>：SELinux 上下文</li><li><code>Access</code>、<code>Modify</code>、<code>Change</code>、<code>Birth</code>：文件被訪問、修改、更改狀態以及創建時的時間戳</li></ul><h3 id="精簡輸出" tabindex="-1">精簡輸出 <a class="header-anchor" href="#精簡輸出" aria-label="Permalink to “精簡輸出”">​</a></h3>`,6)),e("p",null,[s[4]||(s[4]=t("對於精通輸出或者想要使用其它工具（例如：",-1)),l(n,{href:"https://opensource.com/article/20/9/awk-ebook"},{default:i(()=>[...s[3]||(s[3]=[t("awk",-1)])]),_:1}),s[5]||(s[5]=t("）解析輸出的人，這裏可以使用 ",-1)),s[6]||(s[6]=e("code",null,"--terse",-1)),s[7]||(s[7]=t("（短參數為 ",-1)),s[8]||(s[8]=e("code",null,"-t",-1)),s[9]||(s[9]=t("）參數，實現沒有標題或換行符的格式化輸出。",-1))]),s[38]||(s[38]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat --terse planets.xml</span></span>
<span class="line"><span>planets.xml 325 8 81b4 100977 100 fd03 140217 1 0 0 1629181617 1629181618 1629181618 1629181617 4096 unconfined_u:object_r:user_home_t:s0</span></span></code></pre></div><h3 id="自定義格式" tabindex="-1">自定義格式 <a class="header-anchor" href="#自定義格式" aria-label="Permalink to “自定義格式”">​</a></h3>`,2)),e("p",null,[s[11]||(s[11]=t("你可以使用 ",-1)),s[12]||(s[12]=e("code",null,"--printf",-1)),s[13]||(s[13]=t(" 參數以及與 ",-1)),l(n,{href:"https://opensource.com/article/20/8/printf"},{default:i(()=>[...s[10]||(s[10]=[t("printf",-1)])]),_:1}),s[14]||(s[14]=t(" 類似的語法定義自己的輸出格式。",-1)),s[15]||(s[15]=e("code",null,"stat",-1)),s[16]||(s[16]=t(" 的每一個屬性都有一個格式序列（",-1)),s[17]||(s[17]=e("code",null,"%C",-1)),s[18]||(s[18]=t(" 表示 SELinux 上下文，",-1)),s[19]||(s[19]=e("code",null,"%n",-1)),s[20]||(s[20]=t(" 表示文件名等等），所以，你可以定義輸出格式。",-1))]),s[39]||(s[39]=a(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat --printf=&quot;%n\\n%C\\n&quot; planets.xml</span></span>
<span class="line"><span>planets.xml</span></span>
<span class="line"><span>unconfined_u:object_r:user_home_t:s0</span></span>
<span class="line"><span>$ $ stat --printf=&quot;Name: %n\\nModified: %y\\n&quot; planets.xml</span></span>
<span class="line"><span>Name: planets.xml</span></span>
<span class="line"><span>Modified: 2021-08-17 18:26:58.738332799 +1200</span></span></code></pre></div><p>下面是一些常見的格式序列：</p><ul><li><code>%a</code> 訪問權限</li><li><code>%F</code> 文件類型</li><li><code>%n</code> 文件名</li><li><code>%U</code> 用户名</li><li><code>%u</code> 用户 ID</li><li><code>%g</code> 組 ID</li><li><code>%w</code> 創建時間</li><li><code>%y</code> 修改時間</li></ul><p>在 <code>stat</code> 手冊和 <code>coreutils</code> 信息頁中都有完整的格式化序列列表。</p><h3 id="文件信息" tabindex="-1">文件信息 <a class="header-anchor" href="#文件信息" aria-label="Permalink to “文件信息”">​</a></h3><p>如果你曾嘗試解析過 <code>ls -l</code> 的輸出，那麼，你會很喜歡 <code>stat</code> 命令的靈活性。你並不是每次都需要 <code>stat</code> 提供的所有信息，但是，當你需要其中一些或全部的時候它是非常有用的。不管你是讀取默認輸出，還是你自己創建的查詢輸出，<code>stat</code> 命令都可以查看所需的數據。</p><hr>`,7)),e("p",null,[s[22]||(s[22]=t("via: ",-1)),l(n,{href:"https://opensource.com/article/21/8/linux-stat-file-status"},{default:i(()=>[...s[21]||(s[21]=[t("https://opensource.com/article/21/8/linux-stat-file-status",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=t("作者：",-1)),l(n,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[23]||(s[23]=[t("Seth Kenlon",-1)])]),_:1}),s[28]||(s[28]=t(" 選題：",-1)),l(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[24]||(s[24]=[t("lujun9972",-1)])]),_:1}),s[29]||(s[29]=t(" 譯者：",-1)),l(n,{href:"https://github.com/New-World-2019"},{default:i(()=>[...s[25]||(s[25]=[t("New-World-2019",-1)])]),_:1}),s[30]||(s[30]=t(" 校對：",-1)),l(n,{href:"https://github.com/turbokernel"},{default:i(()=>[...s[26]||(s[26]=[t("turbokernel",-1)])]),_:1})]),e("p",null,[s[33]||(s[33]=t("本文由 ",-1)),l(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[31]||(s[31]=[t("LCTT",-1)])]),_:1}),s[34]||(s[34]=t(" 原創編譯，",-1)),l(n,{href:"https://linux.cn/"},{default:i(()=>[...s[32]||(s[32]=[t("Linux中國",-1)])]),_:1}),s[35]||(s[35]=t(" 榮譽推出",-1))])])}const C=o(u,[["render",f]]);export{T as __pageData,C as default};
